```rust
fn paired<'a>(a: &'a [i32], b: &'a [i32]) -> Vec<(&'a i32, &'a i32)> {
    a.iter().zip(b.iter()).collect()
}

fn main() {
    let v1 = vec![1, 2];
    let v2 = vec![3, 4];
    let p = paired(&v1, &v2);
    // The issue is that we're dropping v1 while p still holds references to it.
    // Since p contains references to elements from both v1 and v2, both need to outlive p.
    // We can fix this by ensuring v1 and v2 live at least as long as p.
    println!("{:?}", p);
    drop(v1);
    drop(v2);
}
```

